/* Growtion flowers: the user's leaf and petal drawings, assembled into one low-res (PS2-style) flower.
   Exposes window.Flower = {ready, paint(canvas, recipe), recipe(n), name(r), number(r), TOTAL, PARTS}. */
(function(){
const LO = 160;
const SKETCH={"leaf": ["", "", "", "", "", "", "", "", "", ""], "pet": ["", "", "", "", "", "", "", "", "", "", ""]};
const PARTS = [
  {key:'bg',   name:'背景', en:'BACKGROUND', opts:['夕陽丘','綠螢幕','星夜','沙漠','夜店','花園','墓園']},
  {key:'leaf', name:'葉子', en:'LEAVES',     opts:['對生葉','垂葉','小芽','圓葉枝','果枝','羽枝','劍葉','短枝','蕨枝','長葉']},
  {key:'cal',  name:'花托', en:'CALYX',      opts:['杯托','星萼','圓托','長萼']},
  {key:'pet',  name:'花瓣', en:'PETALS',     opts:['紅彼岸','暗紅玫瑰','淡紫蘭','粉繡球','米色玫瑰苞','白梅','黃菊','淡藍雲朵','紫穗','淡粉鬱金香','鵝黃百合']},
];
// petal colours: [outline, fill]
const PCOL = [['#8c1414','#e0383a'],['#3e0a10','#8e1a28'],['#6a4c9a','#cdb8ee'],['#b03a70','#f6a6c8'],['#8a7458','#ece0c4'],['#9a9088','#fbf8f2'],
              ['#a87808','#f6d03c'],['#3e6a98','#b4d4f2'],['#4a2a78','#a888d8'],['#c06a88','#fbd0dc'],['#a08a30','#fbeea0']];

const hsl = (h,s,l,a=1) => `hsla(${h},${s}%,${l}%,${a})`;
function poly(c, pts, fill){ c.beginPath(); pts.forEach(([x,y],i)=> i?c.lineTo(x,y):c.moveTo(x,y)); c.closePath(); c.fillStyle=fill; c.fill(); }
const P = (cx,cy,a,r) => [cx+Math.cos(a)*r, cy+Math.sin(a)*r];
let seed = 1; const rnd = () => (seed = (seed*16807) % 2147483647) / 2147483647;
function blade(c, x, y, a, len, wid, h, s, l){
  const tip = P(x,y,a,len), m1 = P(x,y,a,len*.45), L = P(m1[0],m1[1],a-Math.PI/2,wid), R = P(m1[0],m1[1],a+Math.PI/2,wid);
  poly(c,[[x,y],L,tip],hsl(h,s,l+8)); poly(c,[[x,y],tip,R],hsl(h,s,l-6));
}
const bands = (c, cols, h) => cols.forEach((col,i)=>{ c.fillStyle=col; c.fillRect(0,i*h,LO,h); });

/* sketches -> canvases (petals recoloured by lightness: outline colour for the strokes, fill colour for the inside) */
const hex = h => [1,3,5].map(i=>parseInt(h.slice(i,i+2),16));
const mix = (a,b,t) => a.map((v,i)=>v+(b[i]-v)*t);
function loadImg(b64){ return new Promise(r=>{ const im=new Image(); im.onload=()=>r(im); im.src='data:image/png;base64,'+b64; }); }
function toCanvas(im){ const c=document.createElement('canvas'); c.width=im.width; c.height=im.height; c.getContext('2d').drawImage(im,0,0); return c; }
function recolor(src, [ln, fl]){
  const c=toCanvas(src), x=c.getContext('2d'), d=x.getImageData(0,0,c.width,c.height), p=d.data, L1=hex(ln), F1=hex(fl), W=[255,255,255];
  for(let i=0;i<p.length;i+=4){ if(!p[i+3]) continue;
    const L=(Math.max(p[i],p[i+1],p[i+2])+Math.min(p[i],p[i+1],p[i+2]))/510;
    const o = L<.85 ? mix(L1,F1,Math.max(0,(L-.5)/.35)) : mix(F1,W,(L-.85)/.15*.3);
    p[i]=o[0]; p[i+1]=o[1]; p[i+2]=o[2]; }
  x.putImageData(d,0,0); return c;
}
function fit(c, img, maxW, maxH, cx, bottom){
  const k=Math.min(maxW/img.width, maxH/img.height), w=img.width*k, h=img.height*k;
  c.imageSmoothingEnabled=true; c.imageSmoothingQuality='high'; c.drawImage(img, cx-w/2, bottom-h, w, h);
}

let LEAF=[], PET=[];
/* join points the user set in the flower prototype (normalised to each drawing); leaves use the topmost pixel */
const ANCH = {leaf:{}, pet:{0:[.461,.511],1:[.482,.53],2:[.508,.765],3:[.51,.553],4:[.481,.917],5:[.504,.545],6:[.541,.548],7:[.501,.181],8:[.601,.757],9:[.504,.907],10:[.594,.903]}}, DEF = {leaf:[], pet:[]};
function topPoint(cv){ const d=cv.getContext('2d').getImageData(0,0,cv.width,cv.height).data;
  for(let y=0;y<cv.height;y++) for(let x=0;x<cv.width;x++) if(d[(y*cv.width+x)*4+3]>160) return [x/cv.width, y/cv.height];
  return [.5,0]; }
const anchor = (k,i) => ANCH[k][i] || DEF[k][i];
const LEAFBOX = {w:72, h:96, cx:80, bottom:158}, PETBOX = {w:70, h:62};
function box(img, w, h){ const k=Math.min(w/img.width, h/img.height); return [img.width*k, img.height*k]; }
function leafRect(i){ const [w,h]=box(LEAF[i],LEAFBOX.w,LEAFBOX.h); return [LEAFBOX.cx-w/2, LEAFBOX.bottom-h, w, h]; }
function joint(i){ const [x,y,w,h]=leafRect(i), [ax,ay]=anchor('leaf',i); return [x+ax*w, y+ay*h]; }

const DRAW = {
  bg:[
    c=>{ bands(c,['#3b1c3a','#5a2340','#8a3440','#c25a3a','#e88a3e'],24);
         c.fillStyle='#f5c26b'; c.beginPath(); c.arc(118,104,14,0,7); c.fill();
         poly(c,[[0,118],[40,100],[78,116],[120,98],[160,112],[160,160],[0,160]],'#2a1c22');
         poly(c,[[0,136],[50,124],[100,138],[160,126],[160,160],[0,160]],'#1a1216'); },
    c=>{ c.fillStyle='#07140a'; c.fillRect(0,0,LO,LO);
         c.fillStyle='rgba(142,245,154,.16)'; for(let i=0;i<LO;i+=16){ c.fillRect(i,0,1,LO); c.fillRect(0,i,LO,1); }
         c.fillStyle='rgba(142,245,154,.08)'; for(let y=0;y<LO;y+=2) c.fillRect(0,y,LO,1);
         poly(c,[[0,140],[160,140],[160,160],[0,160]],'#0d2a12'); },
    c=>{ bands(c,['#070a1c','#0b1030','#121a44','#1b2558'],40);
         seed=7; for(let i=0;i<70;i++){ const x=rnd()*LO|0, y=rnd()*120|0, b=rnd(); c.fillStyle=hsl(50,80,70+b*30,.5+b*.5); c.fillRect(x,y,b>.85?2:1,b>.85?2:1); }
         poly(c,[[24,22],[34,18],[40,26],[36,36],[26,36],[20,28]],'#f2eccc'); poly(c,[[28,22],[34,20],[30,30]],'#c9c2a2');
         poly(c,[[0,140],[60,130],[160,142],[160,160],[0,160]],'#0a0d18'); },
    // 沙漠
    c=>{ bands(c,['#e9d6a4','#e4c98c','#dcb978','#d2a866'],30);
         c.fillStyle='#fff0c0'; c.beginPath(); c.arc(124,30,12,0,7); c.fill();
         poly(c,[[0,112],[50,96],[100,110],[160,92],[160,160],[0,160]],'#c89a5a');
         poly(c,[[0,132],[60,118],[120,134],[160,124],[160,160],[0,160]],'#a87a42');
         poly(c,[[24,120],[28,120],[28,98],[24,98]],'#5f7a3a'); poly(c,[[18,110],[24,110],[24,106],[18,106]],'#5f7a3a'); poly(c,[[18,110],[20,110],[20,102],[18,102]],'#5f7a3a');
         poly(c,[[28,106],[33,106],[33,102],[28,102]],'#4c6630'); poly(c,[[31,106],[33,106],[33,98],[31,98]],'#4c6630'); },
    // 夜店
    c=>{ c.fillStyle='#0a0609'; c.fillRect(0,0,LO,LO);
         [[20,'rgba(255,90,180,.28)'],[80,'rgba(255,140,210,.22)'],[140,'rgba(200,80,255,.22)']].forEach(([x,col],i)=>poly(c,[[x,0],[x-3,0],[x-36+i*30,140],[x+20+i*10,140]],col));
         const g=[]; for(let i=0;i<8;i++) g.push(P(80,14,i/8*Math.PI*2,9)); poly(c,g,'#c8c0cc');
         for(let i=0;i<8;i+=2) poly(c,[[80,14],g[i],g[i+1]],'#8a8090');
         c.fillStyle='#ff4fa8'; for(let y=140;y<160;y+=5) c.fillRect(0,y,LO,1); for(let x=0;x<LO;x+=12) c.fillRect(x,140,1,20);
         c.fillStyle='rgba(255,79,168,.18)'; c.fillRect(0,140,LO,20); },
    // 花園
    c=>{ c.fillStyle='#efede6'; c.fillRect(0,0,LO,100);
         c.fillStyle='#d6d2c6'; for(let y=8;y<100;y+=10){ c.fillRect(0,y,LO,1); for(let x=(y/10%2)*12;x<LO;x+=24) c.fillRect(x,y-9,1,9); }
         c.fillStyle='#c4bfb2'; c.fillRect(0,96,LO,4);
         bands; c.fillStyle='#a8c84a'; c.fillRect(0,100,LO,60);
         c.fillStyle='#93b63c'; for(let y=104;y<160;y+=6) for(let x=(y%12?0:5);x<LO;x+=10) poly(c,[[x,y+4],[x+2,y],[x+4,y+4]],'#8cae38'); },
    // 墓園
    c=>{ bands(c,['#8e9a96','#848f8c','#7a8683'],34);
         c.fillStyle='#5e8a48'; c.fillRect(0,102,LO,58); c.fillStyle='#517a3e'; c.fillRect(0,128,LO,32);
         [[22,104,16,26],[124,100,18,30],[54,112,12,18]].forEach(([x,y,w,h])=>{
           poly(c,[[x,y+h],[x,y+5],[x+3,y],[x+w-3,y],[x+w,y+5],[x+w,y+h]],'#9a9a96'); poly(c,[[x+w*.55,y],[x+w-3,y],[x+w,y+5],[x+w,y+h],[x+w*.55,y+h]],'#7e7e7a');
           c.fillStyle='#6a6a66'; c.fillRect(x+w/2-3,y+8,6,1); c.fillRect(x+w/2-1,y+5,2,8); }); },
  ],
  leaf: Array.from({length:10},(_,i)=>c=>{ const [x,y,w,h]=leafRect(i); c.imageSmoothingEnabled=true; c.imageSmoothingQuality='high'; c.drawImage(LEAF[i],x,y,w,h); }),
  cal:[ /* same green as the leaf sketches (#51ac65), lighter tone #7dc18c for the lit side */
    c=>{ poly(c,[[70,62],[90,62],[86,76],[74,76]],'#51ac65'); poly(c,[[70,62],[80,62],[80,76],[74,76]],'#7dc18c'); },
    c=>{ for(let i=0;i<5;i++){ const a=Math.PI*.5+(i-2)*.42; blade(c,80,66,a,14,4,133,36,i%2?50:56); } },
    c=>{ const pts=[]; for(let i=0;i<8;i++) pts.push(P(80,68,i/8*Math.PI*2,9)); poly(c,pts,'#51ac65');
         poly(c,[pts[4],pts[5],pts[6],pts[7],[80,68]],'#7dc18c'); },
    c=>{ poly(c,[[74,60],[86,60],[83,84],[77,84]],'#51ac65'); poly(c,[[74,60],[80,60],[80,84],[77,84]],'#7dc18c');
         blade(c,77,80,Math.PI*.78,10,3,133,36,52); blade(c,83,80,Math.PI*.22,10,3,133,36,48); },
  ],
  pet: Array.from({length:11},(_,i)=>(c,r)=>{ const [jx,jy]=joint(r.leaf), [w,h]=box(PET[i],PETBOX.w,PETBOX.h), [ax,ay]=anchor('pet',i); c.imageSmoothingEnabled=true; c.imageSmoothingQuality='high'; c.drawImage(PET[i], jx-ax*w, jy-ay*h, w, h); }),
};


const BAYER = [0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5];
function finish(lo){
  const c = lo.getContext('2d'), d = c.getImageData(0,0,LO,LO), p = d.data, step = 12;
  for(let y=0;y<LO;y++) for(let x=0;x<LO;x++){ const i=(y*LO+x)*4; if(!p[i+3]) continue;
    const t = (BAYER[(y&3)*4+(x&3)]/16 - .5) * step;
    for(let k=0;k<3;k++) p[i+k] = Math.max(0,Math.min(255, Math.round((p[i+k]+t)/step)*step)); }
  c.putImageData(d,0,0); return lo;
}

/* draw the flower on a 160px canvas and return it (cached per recipe) */
const cache = new Map();
function low(r){
  const key = PARTS.map(p=>r[p.key]).join('.');
  if(cache.has(key)) return cache.get(key);
  const lo = document.createElement('canvas'); lo.width = lo.height = LO; const c = lo.getContext('2d');
  DRAW.bg[r.bg](c, r); DRAW.leaf[r.leaf](c, r);
  const [jx,jy] = joint(r.leaf); c.save(); c.translate(jx-80, jy-66); DRAW.cal[r.cal](c); c.restore();
  DRAW.pet[r.pet](c, r);
  finish(lo); cache.set(key, lo); return lo;
}
/* paint onto any canvas; px (optional) draws it blocky at that resolution, for the growing animation */
function paint(target, r, px){
  const src = low(r), t = target.getContext('2d');
  t.clearRect(0,0,target.width,target.height);
  if(px && px < LO){
    const s = document.createElement('canvas'); s.width = s.height = px;
    const sc = s.getContext('2d'); sc.imageSmoothingEnabled = true; sc.drawImage(src, 0, 0, px, px);
    t.imageSmoothingEnabled = false; t.drawImage(s, 0, 0, target.width, target.height); return;
  }
  t.imageSmoothingEnabled = true; t.imageSmoothingQuality = 'low'; t.drawImage(src, 0, 0, target.width, target.height);
}

const TOTAL = PARTS.reduce((n,p)=>n*p.opts.length,1);
const number = r => PARTS.reduce((n,p)=>n*p.opts.length+r[p.key],0)+1;
const name = r => PARTS[0].opts[r.bg]+'的'+PARTS[3].opts[r.pet];
/* flower n (1, 2, 3 …) always gets the same random parts; the petal never repeats the previous flower's */
function rng(n){ let a = (n*2654435761 ^ 0x9e3779b9) >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ t>>>15, t|1); t ^= t + Math.imul(t ^ t>>>7, t|61); return ((t ^ t>>>14) >>> 0) / 4294967296; }; }
const recipes = [];
function recipe(n){
  for(let k=recipes.length+1; k<=n; k++){
    const R = rng(k), r = Object.fromEntries(PARTS.map(p=>[p.key, R()*p.opts.length|0]));
    const prev = recipes[k-2];
    while(prev && r.pet===prev.pet) r.pet = R()*PARTS[3].opts.length|0;
    recipes.push(r);
  }
  return recipes[n-1];
}

const ready = Promise.all([...SKETCH.leaf.map(loadImg), ...SKETCH.pet.map(loadImg)]).then(ims=>{
  LEAF = ims.slice(0,10).map(toCanvas);
  PET = ims.slice(10).map((im,i)=>recolor(im, PCOL[i]));
  DEF.leaf = LEAF.map(topPoint); DEF.pet = PET.map(()=>[.5,.85]);
});
window.Flower = {ready, paint, recipe, name, number, TOTAL, PARTS};
})();
